import re

# Define LuaTable with attribute access
class LuaTable(dict):
    def __getattr__(self, name):
        try:
            return self[name]
        except KeyError:
            raise AttributeError(name)
    def __setattr__(self, name, value):
        self[name]=value
    def __getitem__(self, key):
        # Lua allows 1-indexed array access and string keys
        # For simplicity, use dict get
        return super().get(key, None)
    # Need to handle __lua_len etc.

def __lua_table(d):
    return LuaTable(d)

def __lua_len(x):
    if isinstance(x, (str, list, dict, LuaTable)):
        return len(x)
    if x is None:
        return 0
    return len(str(x))

def lex(s):
    TOK_KEYWORD={'and','break','do','else','elseif','end','false','for','function','goto','if','in','local','nil','not','or','repeat','return','then','until','while'}
    i=0; n=len(s); tokens=[]
    while i<n:
        c=s[i]
        if c.isspace():
            i+=1; continue
        if c=='-' and i+1<n and s[i+1]=='-':
            if i+2<n and s[i+2]=='[':
                level=0; k=i+2
                while k<n and s[k]=='=':
                    level+=1; k+=1
                if k<n and s[k]=='[':
                    close=']'+'='*level+']'
                    end=s.find(close, k+1)
                    if end==-1:
                        break
                    i=end+len(close)
                    continue
            j=s.find('\n',i)
            if j==-1: break
            i=j+1; continue
        if c in ('"',"'"):
            quote=c; j=i+1
            while j<n:
                if s[j]=='\\': j+=2; continue
                if s[j]==quote: j+=1; break
                j+=1
            tokens.append(('STRING', s[i:j])); i=j; continue
        if c=='[':
            level=0; k=i+1
            while k<n and s[k]=='=':
                level+=1; k+=1
            if k<n and s[k]=='[':
                close=']'+'='*level+']'
                end=s.find(close, k+1)
                if end==-1: end=n-len(close)
                else: end+=len(close)
                tokens.append(('STRING', s[i:end])); i=end; continue
            tokens.append(('SYMBOL', c)); i+=1; continue
        if c.isalpha() or c=='_':
            j=i
            while j<n and (s[j].isalnum() or s[j]=='_'): j+=1
            word=s[i:j]
            if word in TOK_KEYWORD: tokens.append(('KEYWORD', word))
            else: tokens.append(('NAME', word))
            i=j; continue
        if c.isdigit() or (c=='.' and i+1<n and s[i+1].isdigit()):
            j=i
            if s[i]=='0' and i+1<n and s[i+1] in 'xX':
                j+=2
                while j<n and s[j] in '0123456789abcdefABCDEF': j+=1
            else:
                has_e=False
                while j<n:
                    if s[j].isdigit(): j+=1
                    elif s[j]=='.' and not has_e:
                        if j+1<n and s[j+1]=='.': break
                        j+=1
                    elif s[j] in 'eE' and not has_e:
                        has_e=True; j+=1
                        if j<n and s[j] in '+-': j+=1
                    else: break
            tok=s[i:j]
            if ".." in tok:
                idx=tok.find("..")
                tok=tok[:idx]
                j=i+idx
